import{c as a,Q as e,j as i,m as l}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"SetFixSplit","description":"","frontmatter":{},"headers":[{"level":1,"title":"SetFixSplit","slug":"setfixsplit"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Tiling侧接口/Matmul-Tiling类/SetFixSplit.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Tiling侧接口/Matmul-Tiling类/SetFixSplit.md"}'),s={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Tiling侧接口/Matmul-Tiling类/SetFixSplit.md"};function n(r,t,d,o,p,h){return e(),i("div",null,[...t[0]||(t[0]=[l(`<h1 id="setfixsplit" tabindex="-1">SetFixSplit <a class="header-anchor" href="#setfixsplit" aria-label="Permalink to &quot;SetFixSplit&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>设置固定的baseM、baseN、baseK，单位为元素个数。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int32_t SetFixSplit(int32_t baseMIn = -1, int32_t baseNIn = -1, int32_t baseKIn = -1)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>baseMIn</td><td>输入</td><td>设置固定的baseM，默认值为-1，表示不设置固定baseM，由tiling函数进行计算。</td></tr><tr><td>baseNIn</td><td>输入</td><td>设置固定的baseN，默认值为-1，表示不设置固定baseN，由tiling函数进行计算。</td></tr><tr><td>baseKIn</td><td>输入</td><td>当前仅支持取值为-1，暂不支持设置其它值。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>-1表示设置失败；0表示设置成功。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>baseM*baseN个输出元素所占的存储空间大小不能超过L0C Buffer大小，即baseM * baseN * sizeof(<a href="./../../Matmul-Kernel侧接口/Matmul使用说明.html#p128866505123">C_TYPE</a>) &lt;= L0CSize。</li><li>baseM需要小于等于singleM按16个元素向上对齐后的值（如ceil(singleM/16)*16），baseN需要小于等于singleN以C0_size个元素向上对齐的值，其中singleM为单核内M轴长度，singleN为单核内N轴长度，half/bfloat16_t数据类型的C0_size为16，float数据类型的C0_size为8，int8_t数据类型的C0_size为32，int4b_t数据类型的C0_size为64。例如singleM=12，则baseM需要小于等于16，同时baseM需要满足<a href="./../../../../基础API/矩阵计算（ISASI）/矩阵计算/Mmad.html#section618mcpsimp">分形对齐</a>的要求，所以baseM只能取16；如果baseM取其他超过16的值，获取Tiling将失败。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());</span></span>
<span class="line"><span>matmul_tiling::MatmulApiTiling tiling(ascendcPlatform); </span></span>
<span class="line"><span></span></span>
<span class="line"><span>tiling.SetFixSplit(16, 16, -1);  // 设置固定的baseM、baseN</span></span></code></pre></div>`,14)])])}const u=a(s,[["render",n]]);export{b as __pageData,u as default};
